import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { afterEach, describe, expect, it, vi } from "vitest";
import {
	POSTHOG_PROJECT_ID,
	sourceMapUploadConfig,
	sourceMapUploadKey,
	withSourceMapUpload,
} from "@/lib/posthog-sourcemaps.mjs";

describe("sourceMapUploadKey", () => {
	it("accepts a personal API key", () => {
		expect(sourceMapUploadKey("phx_abc")).toBe("phx_abc");
	});

	it.each([
		["unset", undefined],
		["empty", ""],
		["the vercel pull placeholder", "[SENSITIVE]"],
		["a public project key", "phc_abc"],
	])("refuses %s", (_label, raw) => {
		expect(sourceMapUploadKey(raw)).toBeUndefined();
	});
});

describe("sourceMapUploadConfig", () => {
	const config = sourceMapUploadConfig("phx_abc", "deadbeef");

	it("targets the OrchestKit project on the EU app host", () => {
		expect(POSTHOG_PROJECT_ID).toBe("236036");
		expect(config.projectId).toBe(POSTHOG_PROJECT_ID);
		expect(config.host).toBe("https://eu.posthog.com");
	});

	it("never serves maps and never fails a deploy", () => {
		expect(config.sourcemaps.deleteAfterUpload).toBe(true);
		expect(config.sourcemaps.failOnError).toBe(false);
	});

	it("binds the upload to the commit, with a stable local fallback", () => {
		expect(config.sourcemaps.releaseVersion).toBe("deadbeef");
		expect(
			sourceMapUploadConfig("phx_abc", undefined).sourcemaps.releaseVersion,
		).toBe("local");
	});
});

describe("withSourceMapUpload", () => {
	const site = { reactStrictMode: true };
	const wrapped = { wrapped: true };
	const load = () =>
		Promise.resolve({ withPostHogConfig: vi.fn(() => wrapped) });

	afterEach(() => {
		vi.restoreAllMocks();
	});

	it("never loads the wrapper without a personal API key", async () => {
		const spy = vi.fn(load);
		expect(await withSourceMapUpload(site, {}, spy)).toBe(site);
		expect(spy).not.toHaveBeenCalled();
	});

	it("warns and skips on a malformed key", async () => {
		const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
		const spy = vi.fn(load);
		const env = { POSTHOG_API_KEY: "phc_abc" };
		expect(await withSourceMapUpload(site, env, spy)).toBe(site);
		expect(spy).not.toHaveBeenCalled();
		expect(warn).toHaveBeenCalledOnce();
	});

	it("wraps the config when the key is valid", async () => {
		const env = { POSTHOG_API_KEY: "phx_abc", VERCEL_GIT_COMMIT_SHA: "abc" };
		expect(await withSourceMapUpload(site, env, load)).toBe(wrapped);
	});

	// The package is an optional dependency: when its CLI cannot download, npm
	// drops it and the import fails. That must cost the upload, never the deploy.
	it("skips the upload when the package is not installed", async () => {
		const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
		const env = { POSTHOG_API_KEY: "phx_abc" };
		const missing = () => Promise.reject(new Error("Cannot find package"));
		expect(await withSourceMapUpload(site, env, missing)).toBe(site);
		expect(warn).toHaveBeenCalledOnce();
	});
});

describe("the install does not depend on releases.posthog.com", () => {
	const read = (file: string) =>
		JSON.parse(readFileSync(resolve(__dirname, "..", file), "utf8"));

	it("declares the wrapper as an optional dependency", () => {
		const pkg = read("package.json");
		expect(pkg.optionalDependencies["@posthog/nextjs-config"]).toBeDefined();
		expect(pkg.dependencies["@posthog/nextjs-config"]).toBeUndefined();
	});

	// The CLI's postinstall downloads from that host and exits 1 on failure. An
	// optional flag in the lockfile is what lets npm ci survive it.
	it("locks the CLI as optional", () => {
		const lock = read("package-lock.json");
		expect(lock.packages["node_modules/@posthog/cli"].optional).toBe(true);
	});
});
